#include "stdafx.h"#include "Get2Buffer.h"#include <macros/AutoCloser.h>void* Get2Buffer( LPCSTR pszFile, DWORD &size ){  size = 0;  KAutoCloser<HANDLE> hClose( CreateFileA( pszFile,                                            GENERIC_READ,                                            FILE_SHARE_READ,                                            NULL,                                            OPEN_EXISTING,                                            0,                                            NULL ),                               CloseHandle );  if( hClose==INVALID_HANDLE_VALUE )    return NULL;  size = GetFileSize( hClose, NULL );  BYTE * pData = new BYTE[size];  DWORD Lr = 0;  ReadFile( hClose, pData, size, &Lr, NULL );  ASSD( Lr==size );  return pData;}void ClearBuffer( void *pMem ){  delete pMem;}BOOL GetAttr( const char* name, _WIN32_FILE_ATTRIBUTE_DATA& attr  ){  return ::GetFileAttributesEx( name, GetFileExInfoStandard, &attr );}bool EqAttr( _WIN32_FILE_ATTRIBUTE_DATA& a, FILETIME& b ){  return a.ftLastWriteTime.dwHighDateTime == b.dwHighDateTime && a.ftLastWriteTime.dwLowDateTime  == b.dwLowDateTime;}